=== file: main.loom ===
budget { tokens: 4000 calls: 8 }

tool ReviewReader {
    use: http
    base_url: env.REVIEW_PLATFORM_BASE_URL
    auth_header: "Authorization"
    auth_value: env.REVIEW_PLATFORM_TOKEN
    allow_paths: "/v1/reviews/*"
    methods: "GET"
}

tool ReviewPublisher {
    use: http
    base_url: env.REVIEW_PLATFORM_BASE_URL
    auth_header: "Authorization"
    auth_value: env.REVIEW_PLATFORM_TOKEN
    allow_paths: "/v1/reviews/*/reply"
    methods: "POST"
}

agent ReplyDrafter {
    model: "gpt-6-luna"
    prompt: "reply-drafter"
    tools: [ReviewReader]
    max_iterations: 4
    temperature: 0.2
    guard { pii: mask }
    output_schema: {
        rating: number,
        draft: string
    }
}

workflow Main(review_reference_code) {
    human_prompt "PlatformConfigurator: confirm the review platform endpoint and credentials are configured. Answer ready or not-ready." -> platform_readiness_answer

    alt (platform_readiness_answer == "ready") {
        delegate "Use the read-only review platform tool to fetch the review identified by {review_reference_code}. Draft a courteous reply appropriate to its rating. Return the review rating and draft only." to ReplyDrafter -> review_reply_record expecting {
            rating: number,
            draft: string
        } retry 1 backoff 2s timeout 30s on_failure {
            note "Review reading or reply drafting failed. No publication was attempted."
        }

        alt (review_reply_record.rating < 1) {
            halt "The review rating is missing or invalid. No reply was published."
        } else {
            alt (review_reply_record.rating > 5) {
                halt "The review rating is missing or invalid. No reply was published."
            } else {
                alt (review_reply_record.rating < 4) {
                    human_prompt "BadReviewApprover: review rated 1–3 stars. Approve this draft? Answer yes or no.\n\nDraft:\n{review_reply_record.draft}" -> bad_review_approval_answer

                    alt (bad_review_approval_answer == "yes") {
                        human_prompt "PublishApprover: approve the platform write for this reply? Answer yes or no.\n\nDraft:\n{review_reply_record.draft}" -> platform_write_approval_answer

                        alt (platform_write_approval_answer == "yes") {
                            return { status: "APPROVED_PUBLICATION_NOT_EXECUTED", draft: "{review_reply_record.draft}" }
                        } else {
                            return { status: "PUBLICATION_REJECTED", draft: "{review_reply_record.draft}" }
                        }
                    } else {
                        return { status: "BAD_REVIEW_APPROVAL_REJECTED", draft: "{review_reply_record.draft}" }
                    }
                } else {
                    human_prompt "PublishApprover: approve the platform write for this reply? Answer yes or no.\n\nDraft:\n{review_reply_record.draft}" -> platform_write_approval_answer

                    alt (platform_write_approval_answer == "yes") {
                        return { status: "APPROVED_PUBLICATION_NOT_EXECUTED", draft: "{review_reply_record.draft}" }
                    } else {
                        return { status: "PUBLICATION_REJECTED", draft: "{review_reply_record.draft}" }
                    }
                }
            }
        }
    } else {
        halt "Platform configuration was not confirmed. No review was read or published."
    }
}
